<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount} from 'vue';import {ContextMenuRoot,ContextMenuTrigger,ContextMenuPortal,ContextMenuContent,ContextMenuItem} from 'reka-ui';
import type {WorkspaceFile} from '../../shared/workspace';
const props=defineProps<{files:WorkspaceFile[];expanded:string[];active:string;disabled:boolean;theme:string}>();
const emit=defineEmits<{open:[file:string];expand:[files:string[]];action:[action:string,file:string];resize:[width:number]}>();
const host=ref<HTMLElement>();let observer:ResizeObserver|undefined;onMounted(()=>{observer=new ResizeObserver(entries=>{const width=Math.round(entries[0].borderBoxSize[0].inlineSize);if(width>=120&&width<=420)emit('resize',width);});if(host.value)observer.observe(host.value);});onBeforeUnmount(()=>observer?.disconnect());
function navigate(event:KeyboardEvent){
 const buttons=Array.from(host.value?.querySelectorAll<HTMLButtonElement>('.tree-file')??[]),index=buttons.indexOf(event.target as HTMLButtonElement);if(index<0)return;
 const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:event.key==='ArrowDown'?Math.min(index+1,buttons.length-1):Math.max(0,index-1);buttons[next]?.focus();
}
const visible=computed(()=>props.files.filter(file=>{const parts=file.path.split('/');for(let i=1;i<parts.length;i++)if(!props.expanded.includes(parts.slice(0,i).join('/')))return false;return true;}));
function toggle(file:WorkspaceFile){if(file.directory)emit('expand',props.expanded.includes(file.path)?props.expanded.filter(f=>f!==file.path):[...props.expanded,file.path]);else emit('open',file.path);}
</script>
<template><aside ref="host" class="file-tree" aria-label="项目文件"><div class="tree-heading"><strong>文件</strong><button title="新建文件" aria-label="新建项目文件" :disabled="disabled" @click="emit('action','newFile','')">＋</button><button title="新建文件夹" aria-label="新建文件夹" :disabled="disabled" @click="emit('action','newFolder','')">▱</button><button title="折叠全部文件夹" aria-label="折叠全部文件夹" :disabled="disabled||!expanded.length" @click="emit('action','collapseAll','')"><svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M6 3h7v7M3 6h7v7H3V6Zm2 3.5h3" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg></button><button title="收起侧栏" aria-label="收起侧栏" @click="emit('action','collapse','')">‹</button></div><div class="tree-items" role="tree" @keydown.down.prevent="navigate($event)" @keydown.up.prevent="navigate($event)" @keydown.home.prevent="navigate($event)" @keydown.end.prevent="navigate($event)"><ContextMenuRoot v-for="file in visible" :key="file.path"><ContextMenuTrigger as-child><button role="treeitem" class="tree-file" :class="{selected:active===file.path}" :style="{paddingLeft:(10+(file.path.split('/').length-1)*14)+'px'}" :aria-expanded="file.directory?expanded.includes(file.path):undefined" :aria-selected="active===file.path" :disabled="disabled" :title="file.path" @click="toggle(file)" @keydown.f2.prevent="file.path!=='LPMake.txt'&&emit('action','rename',file.path)" @keydown.delete.prevent="file.path!=='LPMake.txt'&&emit('action','delete',file.path)" @keydown.right.prevent="file.directory&&!expanded.includes(file.path)&&toggle(file)" @keydown.left.prevent="file.directory&&expanded.includes(file.path)&&toggle(file)"><span class="tree-icon">{{file.directory?(expanded.includes(file.path)?'⌄':'›'):file.path==='LPMake.txt'?'⚙':/\.(c|cpp|cc|cxx|h|hpp)$/i.test(file.path)?'C':'·'}}</span><span>{{file.path.split('/').pop()}}</span></button></ContextMenuTrigger><ContextMenuPortal><ContextMenuContent class="tab-context" :data-theme="theme"><ContextMenuItem v-if="file.directory" class="tab-menu-item" @select="emit('action','newFile',file.path)">新建文件…</ContextMenuItem><ContextMenuItem v-if="file.directory" class="tab-menu-item" @select="emit('action','newFolder',file.path)">新建文件夹…</ContextMenuItem><ContextMenuItem class="tab-menu-item" :disabled="file.path==='LPMake.txt'" @select="emit('action','rename',file.path)">重命名…</ContextMenuItem><ContextMenuItem class="tab-menu-item" @select="emit('action','reveal',file.path)">在文件管理器中显示</ContextMenuItem><ContextMenuItem class="tab-menu-item" :disabled="file.path==='LPMake.txt'" @select="emit('action','delete',file.path)">删除…</ContextMenuItem></ContextMenuContent></ContextMenuPortal></ContextMenuRoot></div><button class="tree-build-settings" :disabled="disabled" @click="emit('action','build','LPMake.txt')">项目构建设置…</button></aside></template>
<style>
.file-tree{box-sizing:border-box;display:flex;flex-direction:column;flex-shrink:0;min-width:120px;max-width:420px;background:var(--panel);border-right:1px solid var(--border);overflow:hidden;resize:horizontal;width:190px}.tree-heading{display:flex;align-items:center;height:36px;gap:3px;padding:0 8px;font-size:12px;border-bottom:1px solid var(--border)}.tree-heading strong{margin-right:auto}.tree-heading button{padding:2px 4px;border:0;background:transparent;color:var(--muted)}.tree-items{overflow:auto;flex:1}.tree-file{display:flex;align-items:center;gap:6px;width:100%;border:0;background:transparent;color:var(--text);border-radius:0;padding:6px 10px;text-align:left;font-size:12px;white-space:nowrap}.tree-file>span:last-child{overflow:hidden;text-overflow:ellipsis}.tree-file.selected{background:var(--raised);box-shadow:inset 2px 0 var(--accent)}.tree-file:focus-visible{outline:1px solid var(--accent);outline-offset:-1px}.tree-icon{width:16px;flex-shrink:0;color:var(--muted);font-size:11px}.tree-build-settings{font-size:11px;padding:8px;border:0;border-top:1px solid var(--border);background:transparent;color:var(--muted)}
.editor-workspace{display:flex;flex:1;min-height:0;min-width:0;overflow:hidden}.editor-content{display:flex;flex-direction:column;flex:1;min-width:0;min-height:0}.editor-content>.code-editor{flex:1;min-height:0}.sidebar-toggle{align-self:flex-start;background:transparent;border:0;color:var(--muted);font-size:11px}.editor-content>.sidebar-toggle{position:absolute;z-index:2;bottom:26px;left:6px}
</style>
